-- Built In rotation text: each key is the rotation ID plus .Name or .Description.
if GetLocale() ~= "itIT" then return end
local addon_name = ...
local host = RotationMasterBuiltIns
local L = LibStub("AceLocale-3.0"):GetLocale(host and host.localeName or addon_name:match("^(.-)_[^_]+$") or addon_name)

L["rm.mop.deathknight.blood.Name"] = "Consigliata"
L["rm.mop.deathknight.blood.Description"] = "Consigliata per i difensori Sangue, scelta nella specializzazione Sangue. Ingaggia dalla distanza con Contagio, Tocco Ghiacciato o Presa Mortale. Assalto della Morte sotto metà della salute, ogni volta che manca Scudo del Sangue (dal livello 80), e prima che tutte e quattro le rune del Gelo ed Empie siano piene; Assalto Runico vicino a 90 di potenza runica (Spira Mortale a 80 prima di averlo appreso); Contagio, altrimenti Tocco Ghiacciato e Assalto Pestilenziale, per le malattie, ed Ebollizione del Sangue per rinnovarle dal livello 68; Mietitura dell'Anima sotto il 35%; Assalto al Cuore (Assalto di Sangue prima del livello 60) con due rune del Sangue; Flagello Cremisi su Morte e Distruzione finché durano le malattie, altrimenti Ebollizione del Sangue; Conversione del Sangue a undici cariche; poi Assalto della Morte, Assalto al Cuore, Assalto Runico e Corno Invernale. Tre nemici addosso: Morte e Distruzione, una diffusione delle malattie (Ebollizione del Sangue con Sangue Torbido, altrimenti Pestilenza) ed Ebollizione del Sangue. Promemoria: Presenza Sanguigna quando non ne hai nessuna, Scudo d'Ossa, Corno Invernale, Gelo Mentale, Conversione Runica, Sangue Vampirico, Fermezza Glaciale, Attivazione Runica e Patto con la Morte in base alla tua salute, Arma Runica Danzante sulle élite, Armata dei Morti prima di un boss di gruppo. Non può vedere i danni in arrivo, quindi Scudo Antimagia (disattivato) e le grandi abilità difensive spettano a te."
L["rm.mop.deathknight.blood.simulator.Name"] = "Reattiva alla salute (simulatore)"
L["rm.mop.deathknight.blood.simulator.Description"] = "Un'alternativa alla rotazione integrata Sangue consigliata per i difensori in incursione con i guaritori, disattivata per impostazione predefinita: attivala e disattiva l'altra, oppure alzane la priorità. Assalto della Morte solo sotto il 70% di salute, quando Scudo del Sangue manca o sta per svanire, o prima che le rune del Gelo ed Empie raggiungano il massimo, invece che a ogni runa; una runa del Sangue isolata va ad Assalto al Cuore quando le rune del Gelo ed Empie sono a più di un secondo. Non ha una sezione per gli effetti ad area, e ha gli stessi promemoria di quella consigliata."
L["rm.mop.deathknight.frost.Name"] = "Arma a due mani"
L["rm.mop.deathknight.frost.Description"] = "Gelo con un'arma a due mani, la configurazione abituale per il livellamento; scelta nella specializzazione Gelo ogni volta che la rotazione integrata con due armi non si applica. Stessa apertura, malattie, sopravvivenza ed effetti ad area della rotazione integrata con due armi, poi Disintegrazione con Arma Letale, Assalto del Gelo sopra 76 di potenza runica, Folata Gelida con Brina, Disintegrazione ogni volta che una coppia di rune è piena, Disintegrazione, Folata Gelida, Risucchio della Piaga, Assalto del Gelo a 40 e Corno Invernale. Prima di Disintegrazione (livello 58) Assalto della Morte spende le tue rune Empie. Stessi promemoria della rotazione integrata con due armi."
L["rm.mop.deathknight.frost.dualwield.Name"] = "Due armi"
L["rm.mop.deathknight.frost.dualwield.Description"] = "Consigliata per Gelo con due armi a una mano (Masterfrost); scelta nella specializzazione Gelo quando la tua mano secondaria impugna un'arma. Ingaggia con Contagio o Folata Gelida (Presa Mortale da solo). Assalto della Morte con Energizzazione Oscura o sotto il 35% di salute, Conversione del Sangue a undici cariche, malattie (Sciame Empio, Contagio, Folata Gelida, Assalto Pestilenziale), Mietitura dell'Anima sotto il 35%, Assalto del Gelo con Arma Letale o sopra 89 di potenza runica, Folata Gelida con Brina o con entrambe le rune del Gelo o entrambe le rune della Morte pronte, Disintegrazione con due rune Empie sotto 77 di potenza runica, Assalto del Gelo sopra 76, Disintegrazione, Folata Gelida, Risucchio della Piaga prima che le malattie svaniscano con Contagio pronto, Assalto del Gelo a 40, Corno Invernale. Tre nemici addosso: una diffusione delle malattie, Morte e Distruzione e Folata Gelida. Promemoria: Presenza del Gelo, Pilastro di Ghiaccio, Rianima Cadavere, Attivazione Runica con tutte le rune esaurite, Corno Invernale, Gelo Mentale, Fermezza Glaciale e Patto con la Morte quando sei in difficoltà, Armata dei Morti prima di un boss di gruppo."
L["rm.mop.deathknight.unholy.Name"] = "Empietà"
L["rm.mop.deathknight.unholy.Description"] = "Consigliata per Empietà, e la rotazione integrata per qualsiasi Cavaliere della Morte che Sangue e Gelo non reclamano, incluso uno senza specializzazione. Ingaggia dalla distanza con Contagio o Tocco Ghiacciato (Presa Mortale da solo). Assalto della Morte con Energizzazione Oscura o sotto il 35% di salute, malattie (Sciame Empio, Contagio, Assalto Pestilenziale, Tocco Ghiacciato), Conversione del Sangue a undici cariche, Mietitura dell'Anima sotto il 35%, Trasformazione Oscura a cinque cumuli di Infusione d'Ombra, Spira Mortale vicino al massimo di potenza runica, Morte e Distruzione su un bersaglio che sopravvivrà, Assalto del Flagello, Spira Mortale con Condanna Improvvisa o a 40, Contagio mentre Forza Empia è attiva, Assalto Putrescente (Assalto di Sangue prima di averlo appreso), Risucchio della Piaga, Corno Invernale. Tre nemici addosso: una diffusione delle malattie, Morte e Distruzione, Ebollizione del Sangue e Tocco Ghiacciato su una runa del Gelo. Promemoria: Presenza Empia, il tuo ghoul, Evocazione: Gargoyle durante Brama di Sangue o in un combattimento lungo contro un'élite, Frenesia Empia, Attivazione Runica, Corno Invernale, Gelo Mentale, Fermezza Glaciale e Patto con la Morte quando sei in difficoltà, Armata dei Morti prima di un boss di gruppo; Scudo Antimagia è disattivato."
L["rm.mop.deathknight.unholy.simulator.Name"] = "Empietà, accumulo fino al massimo di rune (simulatore)"
L["rm.mop.deathknight.unholy.simulator.Description"] = "Un'alternativa alla rotazione integrata Empietà consigliata, come la giocano il simulatore, wowtbc.gg, Method e MaxDps; disattivata per impostazione predefinita: attivala e disattiva l'altra, oppure alzane la priorità. Mentre Trasformazione Oscura non è attiva, Spira Mortale serve a ricostruire Infusione d'Ombra, Assalto del Flagello viene per primo quando entrambe le rune Empie o entrambe le rune della Morte sono pronte, e Assalto Putrescente per primo quando lo sono entrambe le rune del Sangue ed entrambe le rune del Gelo; per il resto stessa apertura, malattie, effetti ad area e promemoria di quella consigliata."
L["rm.retail.deathknight.blood.Name"] = "Assistente di Combattimento di Blizzard"
L["rm.retail.deathknight.blood.Description"] = "Consigliata per Sangue. Evidenzia il prossimo incantesimo suggerito dall'Assistente di Combattimento di Blizzard, l'unico consiglio di rotazione che il gioco permette ancora a un addon di leggere in combattimento in Midnight; attende mentre lanci o incanali. Al suo fianco, promemoria per ciò che l'Assistente di Combattimento lascia a te: Sangue Vampirico e Rianimazione Cadavere in combattimento, Gelo Mentale su un lancio interrompibile, e Fermezza Glaciale e il tuo tempo di recupero razziale ogni volta che sono pronti in combattimento. I lanci nemici sono nascosti in combattimento, quindi Gelo Mentale si illumina solo dove il gioco li mostra; la salute è nascosta su Retail, quindi decidi tu quando usare Fermezza Glaciale. I tempi della mitigazione attiva, Scudo Antimagia, le provocazioni e i monili restano a te."
L["rm.retail.deathknight.blood.guide.Name"] = "Riferimento (Icy Veins e Wowhead)"
L["rm.retail.deathknight.blood.guide.Description"] = "Solo riferimento, disattivata per impostazione predefinita: la priorità Sangue delle guide. In combattimento in Midnight i tuoi effetti benefici e le penalità del bersaglio sono nascosti agli addon, quindi i passaggi che li leggono lì restano in attesa; leggila o duplicala per sperimentare. Salute e potenza runica sono nascoste su Retail, quindi Assalto della Morte viene usato ogni volta che te lo puoi permettere. Ingaggia con Carezza della Morte. Assalto della Morte; Strappo Midollare (Carezza della Morte fuori dalla mischia) quando Scudo d'Ossa manca, ha meno di cinque cariche, sta per scadere o è attivo Sterminio; durante Dono dei San'layn, Assalto della Morte, un'Ebollizione del Sangue, Morte e Distruzione con Flagello Cremisi e Assalto al Cuore; Morte e Distruzione con Flagello Cremisi o contro quattro nemici; Assalto Vampirico; Consunzione; Ebollizione del Sangue con Punto di Ebollizione, se manca Piaga del Sangue o a cariche piene; Assalto al Cuore. Promemoria: Rianimazione Cadavere, Sangue Vampirico, Marchio della Mietitrice, Arma Runica Danzante dopo Marchio della Mietitrice, più i promemoria di utilità della rotazione integrata dell'Assistente di Combattimento."
L["rm.retail.deathknight.blood.simc.Name"] = "Araldo della Morte, riferimento (SimulationCraft)"
L["rm.retail.deathknight.blood.simc.Description"] = "Solo riferimento, disattivata per impostazione predefinita: la lista Araldo della Morte di SimulationCraft, che spende la potenza runica su Assalto della Morte per fare danni. I dati di combattimento nascosti le impediscono di funzionare in combattimento in Midnight, e la potenza runica è nascosta su Retail, quindi non c'è alcuno scarico al massimo. Morte e Distruzione ogni volta che non è attivo, Marchio della Mietitrice, Strappo Midollare con Sterminio, Carezza della Morte per Scudo d'Ossa quando scarseggiano le rune (altrimenti Strappo Midollare), Assalto della Morte, Ebollizione del Sangue, Consunzione fuori da Arma Runica Danzante, Assalto al Cuore. Promemoria: Rianimazione Cadavere, Arma Runica Danzante, Sangue Vampirico e i promemoria di utilità."
L["rm.retail.deathknight.frost.Name"] = "Assistente di Combattimento di Blizzard"
L["rm.retail.deathknight.frost.Description"] = "Consigliata per Gelo. Evidenzia il prossimo incantesimo suggerito dall'Assistente di Combattimento di Blizzard, l'unico consiglio di rotazione che il gioco permette ancora a un addon di leggere in combattimento in Midnight; attende mentre lanci o incanali. Al suo fianco, promemoria per ciò che l'Assistente di Combattimento lascia a te: Soffio di Sindragosa e Rianimazione Cadavere in combattimento, Gelo Mentale su un lancio interrompibile, e Fermezza Glaciale e il tuo tempo di recupero razziale ogni volta che sono pronti in combattimento. I lanci nemici sono nascosti in combattimento, quindi Gelo Mentale si illumina solo dove il gioco li mostra; la salute è nascosta su Retail, quindi decidi tu quando usare Fermezza Glaciale."
L["rm.retail.deathknight.frost.guide.Name"] = "Riferimento (Icy Veins e SimulationCraft)"
L["rm.retail.deathknight.frost.guide.Description"] = "Solo riferimento, disattivata per impostazione predefinita: la priorità Gelo delle guide. Arma Letale, Brina e Lama di Ghiaccio sono nascosti in combattimento in Midnight, quindi lì non può funzionare; la potenza runica è nascosta su Retail, quindi non c'è alcun controllo del massimo. Disintegrazione con due cumuli di Arma Letale o con uno e tre rune, Assalto del Gelo su cinque cumuli di Lama di Ghiaccio con Assalto Frantumante, Folata Gelida con Brina, Disintegrazione con Arma Letale, Assalto del Gelo, Disintegrazione; contro tre o più nemici subentrano Falce del Signore del Gelo e Avanzata Glaciale; Folata Gelida fuori dalla mischia. Promemoria: Inverno Spietato, Pilastro di Ghiaccio, Soffio di Sindragosa e Furia del Dragone del Gelo durante Pilastro, Marchio della Mietitrice, Rianimazione Cadavere, Attivazione Runica a due cariche, più i promemoria di utilità."
L["rm.retail.deathknight.frost.wowhead.Name"] = "Riferimento (Wowhead)"
L["rm.retail.deathknight.frost.wowhead.Description"] = "Solo riferimento, disattivata per impostazione predefinita: l'ordine Gelo di Wowhead, che inserisce i tempi di recupero nella rotazione. I dati di combattimento nascosti le impediscono di funzionare in combattimento in Midnight; la potenza runica è nascosta su Retail, quindi non c'è alcun controllo del massimo. Attivazione Runica a due cariche, Marchio della Mietitrice, Pilastro di Ghiaccio, Soffio di Sindragosa, Furia del Dragone del Gelo; poi Disintegrazione con due cumuli di Arma Letale o con uno e Sterminio, Folata Gelida con Brina, Disintegrazione con Arma Letale, Attivazione Runica per ottenerne una nuova, Assalto del Gelo, Disintegrazione, Folata Gelida. Contro tre o più nemici subentrano Falce del Signore del Gelo e Avanzata Glaciale."
L["rm.retail.deathknight.initial.Name"] = "Assistente di Combattimento di Blizzard"
L["rm.retail.deathknight.initial.Description"] = "Consigliata prima di scegliere una specializzazione (mentre il gioco segnala la specializzazione iniziale del Cavaliere della Morte). Evidenzia il prossimo incantesimo suggerito dall'Assistente di Combattimento di Blizzard, l'unico consiglio di rotazione che il gioco permette ancora a un addon di leggere in combattimento in Midnight; attende mentre lanci o incanali. Al suo fianco, i promemoria che ogni rotazione integrata del Cavaliere della Morte condivide, ciascuno una volta che conosci il suo incantesimo. Quando scegli una specializzazione al livello 10, subentrano le rotazioni integrate di quella specializzazione."
L["rm.retail.deathknight.unholy.Name"] = "Assistente di Combattimento di Blizzard"
L["rm.retail.deathknight.unholy.Description"] = "Consigliata per Empietà. Evidenzia il prossimo incantesimo suggerito dall'Assistente di Combattimento di Blizzard, l'unico consiglio di rotazione che il gioco permette ancora a un addon di leggere in combattimento in Midnight (rianima il tuo ghoul e usa da sé Armata dei Morti e Trasformazione Oscura); attende mentre lanci o incanali. Al suo fianco: Gelo Mentale su un lancio interrompibile, e Fermezza Glaciale e il tuo tempo di recupero razziale ogni volta che sono pronti in combattimento. I lanci nemici sono nascosti in combattimento, quindi Gelo Mentale si illumina solo dove il gioco li mostra; la salute è nascosta su Retail, quindi decidi tu quando usare Fermezza Glaciale."
L["rm.retail.deathknight.unholy.guide.Name"] = "Riferimento (Icy Veins e Wowhead)"
L["rm.retail.deathknight.unholy.guide.Description"] = "Solo riferimento, disattivata per impostazione predefinita: la priorità Empietà delle guide. Proc e piaghe sono nascosti in combattimento in Midnight, quindi lì non può funzionare; potenza runica e salute del bersaglio sono nascoste su Retail, quindi la finestra di esecuzione e la spesa di potenza runica dei San'layn sono escluse. Rianima Cadavere senza un ghoul; Falce Putrescente per mantenere attiva la celerità della sua piaga; Mietitura dell'Anima con Mietitura; Putrefazione durante Trasformazione Oscura; Spira Mortale (Epidemia contro quattro o più nemici) con Condanna Improvvisa o Conoscenza Proibita; Assalto Putrescente senza cariche di Ghoul Minore, Assalto del Flagello con le cariche; Spira Mortale. Promemoria: Armata dei Morti, Trasformazione Oscura, Contagio quando mancano le tue piaghe, più i promemoria di utilità."
L["rm.retail.deathknight.unholy.simc.Name"] = "Riferimento (SimulationCraft)"
L["rm.retail.deathknight.unholy.simc.Description"] = "Solo riferimento, disattivata per impostazione predefinita: la lista Empietà di SimulationCraft, che usa Spira Mortale molto più spesso. I dati di combattimento nascosti le impediscono di funzionare in combattimento in Midnight; potenza runica e salute del bersaglio sono nascoste su Retail, quindi i controlli del massimo e dell'esecuzione sono esclusi. Mantenimento di Falce Putrescente, Mietitura dell'Anima durante Trasformazione Oscura, Spira Mortale con Condanna Improvvisa, Putrefazione durante Trasformazione Oscura, Spira Mortale durante Trasformazione Oscura o con Conoscenza Proibita e ogni volta che mancano più di 5 secondi ad Armata dei Morti, Assalto del Flagello con cariche di Ghoul Minore, Assalto Putrescente. Contro tre o più nemici: Epidemia al posto di Spira Mortale e Assalto Putrescente sotto le tre cariche. Promemoria: Contagio, Morte e Distruzione sui gruppi di nemici, Armata dei Morti, Trasformazione Oscura."
